/**
 * Puts jobs left `running` by a dead worker back in the queue. The interrupted attempt is not
 * counted: its claim incremented `attempts`, so that increment is undone and the job is re-run as
 * the same attempt number. Returns how many were requeued.
 */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  const now = new Date().toISOString();
  return transaction(db, () => {
    const result = db
      .prepare(
        `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after_ms = 0, updated_at = ? WHERE status = 'running'`,
      )
      .run(now);
    return Number(result.changes);
  });
}

/** Returns a job interrupted by shutdown to the queue, undoing the attempt it started. */
export function requeueInterrupted(db: DatabaseSync, id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after_ms = 0, updated_at = ? WHERE id = ?`,
  ).run(new Date().toISOString(), id);
}

